package com.smartresponse.api; import com.smartresponse.service.EmergencyAcceptanceService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/emergencies") public class EmergencyAcceptanceController {private final EmergencyAcceptanceService service;public EmergencyAcceptanceController(EmergencyAcceptanceService s){service=s;}@PostMapping("/{id}/accept") public ResponseEntity<Map<String,UUID>> accept(@PathVariable UUID id,Authentication a){return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("assignmentId",service.accept(id,a.getName())));}}
